/**
 * Builds static/superadmin/assets/css/admin.bundle.min.css
 *
 * The admin theme ships ~1.9 MB of CSS (Bootstrap + the full theme with every plugin),
 * while the panel uses a small fraction of it. This script keeps only the rules whose
 * selectors appear in our templates / scripts (PurgeCSS), merges the files into one
 * request and minifies the result.
 *
 * Run after adding NEW theme/Bootstrap classes to templates:   npm install && npm run build:css
 * (style-custom.css is hand-written and loaded separately, so it is never purged.)
 */
import { PurgeCSS } from 'purgecss';
import CleanCSS from 'clean-css';
import { readFileSync, writeFileSync } from 'node:fs';

const ASSETS = 'static/superadmin/assets';
const OUT = `${ASSETS}/css/admin.bundle.min.css`;

// Source files live in assets_src/ (not served). Order matters; `base` is where each file used to sit
// relative to static/.../css/, so its relative url(...) references are rebased to still resolve.
const SRC = 'assets_src/admin-theme';
const SOURCES = [
  { file: `${SRC}/bootstrap.min.css`, base: '../plugins/bootstrap/css/' },
  { file: `${SRC}/style.css`, base: '' },
  { file: `${SRC}/skin-modes.css`, base: '' },
  { file: `${SRC}/color1.css`, base: '../colors/' },
  // feather icons (was a separate icons.css -> @import chain)
  { file: `${SRC}/feather.css`, base: '../iconfonts/feather/' },
];

// Everything that can put a class name into the page
const CONTENT = [
  'templates/**/*.html',
  `${ASSETS}/js/custom.js`,
  `${ASSETS}/js/sticky.js`,
  `${ASSETS}/plugins/bootstrap/js/bootstrap.min.js`,
  `${ASSETS}/plugins/sidemenu/sidemenu.js`,
  `${ASSETS}/plugins/sidebar/sidebar.js`,
  `${ASSETS}/plugins/p-scroll/perfect-scrollbar.js`,
  `${ASSETS}/plugins/summernote/summernote1.js`,
];

// Classes added at runtime by Bootstrap, Summernote, the theme JS and our AJAX code
const SAFELIST = {
  standard: [/^show$/, /^showing$/, /^hiding$/, /^fade$/, /^active$/, /^open$/, /^disabled$/, /^collapse/,
    /^collapsing$/, /^modal/, /^dropdown/, /^tooltip/, /^bs-tooltip/, /^is-expanded$/, /^is-invalid$/, /^was-validated$/,
    /^sidenav-toggled/, /^sidebar-mini$/, /^app$/, /^ltr$/, /^light-mode$/, /^sticky/, /^fixed-header$/, /^note-/,
    /^ps/, /^custom-select/, /^status-/, /^sa-toast/, /^toast-/, /^fade-out$/, /^row-/, /^selected$/, /^check-icon$/],
  deep: [/^note-/, /^modal/, /^dropdown/, /^ps/, /^sidenav-toggled/, /^custom-select/],
  greedy: [/note-/],
};

const css = SOURCES.map(({ file, base }) => {
  let text = readFileSync(file, 'utf8');
  // drop the theme's unused IBM Plex Sans font import (pages use Inter) and source-map comments
  text = text.replace(/@import\s+url\([^)]*fonts\.googleapis[^)]*\);?/g, '').replace(/\/\*# sourceMappingURL=.*?\*\//g, '');
  // rebase relative url(...) so they still resolve from css/
  if (base) {
    text = text.replace(/url\((['"]?)(?!data:|https?:|\/|#)([^'")]+)\1\)/g, (_, q, path) => `url(${q}${base}${path}${q})`);
  }
  return `/* ${file} */\n${text}`;
}).join('\n');

const [result] = await new PurgeCSS().purge({
  content: CONTENT,
  css: [{ raw: css }],
  safelist: SAFELIST,
  fontFace: true,
  keyframes: true,
  variables: false,
});

const minified = new CleanCSS({ level: 1, rebase: false }).minify(result.css);
if (minified.errors.length) throw new Error(minified.errors.join('\n'));
writeFileSync(OUT, `/* NIT admin theme bundle - generated by scripts/build-admin-css.mjs, do not edit */\n${minified.styles}`);
console.log(`input ${(css.length / 1024).toFixed(0)} KB -> ${OUT} ${(minified.styles.length / 1024).toFixed(0)} KB`);
